package sessions

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"

	"github.com/dev1-alexwei-net/guava/conversations"
)

var ErrAccountNotFound = errors.New("executor account not found")

// AccountSettings is the persisted launch configuration for the dashboard's
// active executor account. ID is a version-4 UUID generated by the store.
type AccountSettings struct {
	ID                        string
	Host                      string
	Port                      string
	DatabasePath              string
	RootPath                  string
	FileExplorerURL           string
	GatewayURL                string
	AgentID                   string
	Subdirectory              string
	Instructions              string
	AppendNearestInstructions bool
}

// DefaultAccountSettings returns localhost-safe defaults for a first launch.
func DefaultAccountSettings() AccountSettings {
	instructions, _ := conversations.LookupConstant(conversations.InstructionsKey)
	return AccountSettings{
		Host:                      "127.0.0.1",
		Port:                      "8081",
		DatabasePath:              "fileexplorer.sqlite",
		RootPath:                  ".",
		FileExplorerURL:           "http://127.0.0.1:8080",
		GatewayURL:                "http://127.0.0.1:18789",
		AgentID:                   "main",
		Instructions:              instructions,
		AppendNearestInstructions: true,
	}
}

// EnsureAccount creates the initial account from settings or returns the
// account already stored. Schema creation is additive; existing task-session
// rows and the fileexplorer database are not changed.
func (s *Store) EnsureAccount(ctx context.Context, settings AccountSettings) (AccountSettings, error) {
	if s == nil || s.db == nil {
		return AccountSettings{}, errors.New("task session store is not open")
	}
	settings = withAccountDefaults(settings)

	var account AccountSettings
	err := s.db.QueryRowContext(ctx, `
		SELECT id, host, port, database_path, root_path, fileexplorer_url, gateway_url, agent_id, subdirectory,
			instructions, append_nearest_instructions
		FROM executor_accounts WHERE singleton = 1
	`).Scan(&account.ID, &account.Host, &account.Port, &account.DatabasePath, &account.RootPath,
		&account.FileExplorerURL, &account.GatewayURL, &account.AgentID, &account.Subdirectory,
		&account.Instructions, &account.AppendNearestInstructions)
	if err == nil {
		if err := s.associateLegacySessions(ctx, account.ID); err != nil {
			return AccountSettings{}, err
		}
		return account, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return AccountSettings{}, fmt.Errorf("load executor account: %w", err)
	}

	id, err := newID()
	if err != nil {
		return AccountSettings{}, fmt.Errorf("generate account UUID: %w", err)
	}
	_, err = s.db.ExecContext(ctx, `
		INSERT INTO executor_accounts
			(id, singleton, host, port, database_path, root_path, fileexplorer_url, gateway_url, agent_id, subdirectory,
			 instructions, append_nearest_instructions, created_at)
		VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, unixepoch())
		ON CONFLICT(singleton) DO NOTHING
	`, id, settings.Host, settings.Port, settings.DatabasePath, settings.RootPath,
		settings.FileExplorerURL, settings.GatewayURL, settings.AgentID, settings.Subdirectory,
		settings.Instructions, settings.AppendNearestInstructions)
	if err != nil {
		return AccountSettings{}, fmt.Errorf("initialize executor account: %w", err)
	}

	err = s.db.QueryRowContext(ctx, `
		SELECT id, host, port, database_path, root_path, fileexplorer_url, gateway_url, agent_id, subdirectory,
			instructions, append_nearest_instructions
		FROM executor_accounts WHERE singleton = 1
	`).Scan(&account.ID, &account.Host, &account.Port, &account.DatabasePath, &account.RootPath,
		&account.FileExplorerURL, &account.GatewayURL, &account.AgentID, &account.Subdirectory,
		&account.Instructions, &account.AppendNearestInstructions)
	if err != nil {
		return AccountSettings{}, fmt.Errorf("load executor account: %w", err)
	}
	if err := s.associateLegacySessions(ctx, account.ID); err != nil {
		return AccountSettings{}, err
	}
	return account, nil
}

func withAccountDefaults(settings AccountSettings) AccountSettings {
	defaults := DefaultAccountSettings()
	if settings.Instructions == "" {
		settings.Instructions = defaults.Instructions
		settings.AppendNearestInstructions = defaults.AppendNearestInstructions
	}
	if settings.Host == "" {
		settings.Host = defaults.Host
	}
	if settings.Port == "" {
		settings.Port = defaults.Port
	}
	if settings.DatabasePath == "" {
		settings.DatabasePath = defaults.DatabasePath
	}
	if settings.RootPath == "" {
		settings.RootPath = defaults.RootPath
	}
	if settings.FileExplorerURL == "" {
		settings.FileExplorerURL = defaults.FileExplorerURL
	}
	if settings.GatewayURL == "" {
		settings.GatewayURL = defaults.GatewayURL
	}
	if settings.AgentID == "" {
		settings.AgentID = defaults.AgentID
	}
	return settings
}

// ReplaceAccount atomically replaces the current account and its saved history.
// A failed replacement leaves the old account and sessions intact.
func (s *Store) ReplaceAccount(ctx context.Context, accountID string, settings AccountSettings) (AccountSettings, error) {
	if s == nil || s.db == nil {
		return AccountSettings{}, errors.New("task session store is not open")
	}
	if accountID == "" {
		return AccountSettings{}, errors.New("executor account ID is required")
	}
	settings = withAccountDefaults(settings)
	id, err := newID()
	if err != nil {
		return AccountSettings{}, fmt.Errorf("generate account UUID: %w", err)
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return AccountSettings{}, fmt.Errorf("begin executor account replacement: %w", err)
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, `DELETE FROM session_file_progress WHERE session_id IN (SELECT id FROM task_sessions WHERE account_id = ?)`, accountID); err != nil {
		return AccountSettings{}, fmt.Errorf("delete previous executor account session progress: %w", err)
	}
	result, err := tx.ExecContext(ctx, `DELETE FROM executor_accounts WHERE id = ? AND singleton = 1`, accountID)
	if err != nil {
		return AccountSettings{}, fmt.Errorf("delete previous executor account: %w", err)
	}
	deleted, err := result.RowsAffected()
	if err != nil {
		return AccountSettings{}, fmt.Errorf("check previous executor account deletion: %w", err)
	}
	if deleted == 0 {
		return AccountSettings{}, fmt.Errorf("%w: %q", ErrAccountNotFound, accountID)
	}
	if _, err := tx.ExecContext(ctx, `
		INSERT INTO executor_accounts
			(id, singleton, host, port, database_path, root_path, fileexplorer_url, gateway_url, agent_id, subdirectory,
			 instructions, append_nearest_instructions, created_at)
		VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, unixepoch())
	`, id, settings.Host, settings.Port, settings.DatabasePath, settings.RootPath,
		settings.FileExplorerURL, settings.GatewayURL, settings.AgentID, settings.Subdirectory,
		settings.Instructions, settings.AppendNearestInstructions); err != nil {
		return AccountSettings{}, fmt.Errorf("create replacement executor account: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return AccountSettings{}, fmt.Errorf("commit executor account replacement: %w", err)
	}
	settings.ID = id
	return settings, nil
}

// associateLegacySessions attaches pre-account saved sessions to the account
// created for the existing executor configuration.
func (s *Store) associateLegacySessions(ctx context.Context, accountID string) error {
	if _, err := s.db.ExecContext(ctx, `UPDATE task_sessions SET account_id = ? WHERE account_id IS NULL`, accountID); err != nil {
		return fmt.Errorf("associate legacy task sessions with account: %w", err)
	}
	return nil
}

// DeleteAccount removes an account and all of its saved sessions and file
// progress. The task_sessions foreign key cascades the session deletion.
func (s *Store) DeleteAccount(ctx context.Context, accountID string) error {
	if s == nil || s.db == nil {
		return errors.New("task session store is not open")
	}
	if accountID == "" {
		return errors.New("executor account ID is required")
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin executor account deletion: %w", err)
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, `DELETE FROM session_file_progress WHERE session_id IN (SELECT id FROM task_sessions WHERE account_id = ?)`, accountID); err != nil {
		return fmt.Errorf("delete executor account session progress: %w", err)
	}
	result, err := tx.ExecContext(ctx, `DELETE FROM executor_accounts WHERE id = ?`, accountID)
	if err != nil {
		return fmt.Errorf("delete executor account: %w", err)
	}
	deleted, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("check executor account deletion: %w", err)
	}
	if deleted == 0 {
		return fmt.Errorf("%w: %q", ErrAccountNotFound, accountID)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit executor account deletion: %w", err)
	}
	return nil
}

// migrateAccountInstructions adds instruction preferences to account stores
// created before those settings were persisted.
func (s *Store) migrateAccountInstructions() error {
	columns := make(map[string]bool)
	rows, err := s.db.Query(`PRAGMA table_info(executor_accounts)`)
	if err != nil {
		return fmt.Errorf("inspect executor_accounts schema: %w", err)
	}
	for rows.Next() {
		var cid, notnull, pk int
		var name, colType string
		var dflt any
		if err := rows.Scan(&cid, &name, &colType, &notnull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return fmt.Errorf("inspect executor_accounts schema: %w", err)
		}
		columns[name] = true
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return fmt.Errorf("inspect executor_accounts schema: %w", err)
	}
	if err := rows.Close(); err != nil {
		return fmt.Errorf("inspect executor_accounts schema: %w", err)
	}
	if !columns["instructions"] {
		instructions, _ := conversations.LookupConstant(conversations.InstructionsKey)
		quoted := "'" + strings.ReplaceAll(instructions, "'", "''") + "'"
		if _, err := s.db.Exec(`ALTER TABLE executor_accounts ADD COLUMN instructions TEXT NOT NULL DEFAULT ` + quoted); err != nil {
			return fmt.Errorf("add account instructions: %w", err)
		}
	}
	if !columns["append_nearest_instructions"] {
		if _, err := s.db.Exec(`ALTER TABLE executor_accounts ADD COLUMN append_nearest_instructions INTEGER NOT NULL DEFAULT 1`); err != nil {
			return fmt.Errorf("add nearest instructions preference: %w", err)
		}
	}
	return nil
}
